In 1.37 we can assume workoadbuilder only works if PreemptionPolicy FG is off. ", 'created_at': '2026-07-22T10:46:46+00:00', 'path': 'staging/src/k8s.io/component-helpers/scheduling/schedulingv1/workloadbuilder/types.go', 'position': 1}, {'user': 'mm4tt', 'body': 'Could we consolidate tree traversal and basic structural validation into a single method? It should verify that:

1. Names are always set.
2. Names are unique across the tree.
3. The `WorkloadItem` leaf/composite union is respected (composite nodes set only CPG fields; leaf nodes set only PG fields).

We could then call this method in both `build()` and `validate()`.

Something like:

```go
// validateWorkloadItemTree does a full traversal of the tree to validate 
// basic structural invariants: presence of names, uniqueness of names, 
// and the leaf/composite input union rules.
func validateWorkloadItemTree(root *WorkloadItem) error {
	seen := make(map[string]bool)
	
	var validate func(item *WorkloadItem) error
	validate = func(item *WorkloadItem) error {
		if item == nil {
			return fmt.Errorf("workload item cannot be nil")
		}
		
		if item.Name == "" {
			return fmt.Errorf("workload item name cannot be empty")
		}
		if seen[item.Name] {
			return fmt.Errorf("duplicate workload item name %q: template names must be unique across the Workload", item.Name)
		}
		seen[item.Name] = true

		if err := validateItemInputUnion(item); err != nil {
			return err
		}

		for _, child := range item.Children {
			if err := validate(child); err != nil {
				return err
			}
		}
		return nil
	}

	return validate(root)
}

// validateItemInputUnion enforces the WorkloadInput leaf/composite union
// A composite node must not set any leaf building block, and a leaf
// node must not set any composite building block.
func validateItemInputUnion(item *WorkloadItem) error {
	in := item.Input

	if isComposite(item) {
		if in.Policy.PodGroupData != nil { return fmt.Errorf("composite workload item %q sets leaf building block: policy", item.Name) }
		if in.Constraints.PodGroupData != nil { return fmt.Errorf("composite workload item %q sets leaf building block: constraints", item.Name) }
		if in.DisruptionMode.PodGroupData != nil { return fmt.Errorf("composite workload item %q sets leaf building block: disruptionMode", item.Name) }
		if in.PreemptionPolicy.PodGroupData != nil { return fmt.Errorf("composite workload item %q sets leaf building block: preemptionPolicy", item.Name) }
		if len(in.ResourceClaims.PodGroupData) > 0 { return fmt.Errorf("composite workload item %q sets leaf building block: resourceClaims", item.Name) }
		return nil
	}

	if in.Policy.CompositePodGroupData != nil { return fmt.Errorf("leaf workload item %q sets composite building block: policy", item.Name) }
	if in.Constraints.CompositePodGroupData != nil { return fmt.Errorf("leaf workload item %q sets composite building block: constraints", item.Name) }
	if in.DisruptionMode.CompositePodGroupData != nil { return fmt.Errorf("leaf workload item %q sets composite building block: disruptionMode", item.Name) }
	if in.PreemptionPolicy.CompositePodGroupData != nil { return fmt.Errorf("leaf workload item %q sets composite building block: preemptionPolicy", item.Name) }
	
	return nil
}

```
