 	Devices []Device `json:"devices,omitempty"`
 }
@@ -61,6 +69,8 @@ type DeviceMetadataRequest struct {
 type Device struct {
 	// Driver is the name of the DRA driver that manages this device.
 	// It must be a DNS subdomain no longer than 63 characters.
+	//
